using System; using MySqlConnector; var b = new MySqlConnectionStringBuilder{Server="localhost",UserID="root",Password="123456",Database="pems_db"}; using var conn = new MySqlConnection(b.ConnectionString); conn.Open(); using var cmd = new MySqlCommand("SELECT full_name, organization, member_type FROM visit_guest_members WHERE visit_request_id = 100102;", conn); using var reader = cmd.ExecuteReader(); while(reader.Read()) Console.WriteLine($"Guest: {reader[0]}, Org: {reader[1]}, Type: {reader[2]}");
